import{_ as d,o as r,c as o,ag as n}from"./chunks/framework.KxDd3USm.js";const c=JSON.parse('{"title":"06.2 IP 地址、NAT 与默认网关 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/02-IP地址与网关.md","filePath":"06-计算机网络/02-IP地址与网关.md"}'),s={name:"06-计算机网络/02-IP地址与网关.md"};function a(e,t,g,l,i,h){return r(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="_06-2-ip-地址、nat-与默认网关-★★" tabindex="-1">06.2 IP 地址、NAT 与默认网关 ★★ <a class="header-anchor" href="#_06-2-ip-地址、nat-与默认网关-★★" aria-label="Permalink to &quot;06.2 IP 地址、NAT 与默认网关 ★★&quot;">​</a></h1><h3 id="ip-地址长什么样" tabindex="-1">IP 地址长什么样 <a class="header-anchor" href="#ip-地址长什么样" aria-label="Permalink to &quot;IP 地址长什么样&quot;">​</a></h3><p>IPv4 地址是 <strong>32 位二进制数</strong>，为了人能看懂，每 8 位一组转成十进制、中间用点隔开，叫<strong>点分十进制</strong>，如 <code>192.168.1.1</code>。每组取值 0～255。32 位 = 4 个字节。</p><h3 id="五类地址-必须会判断类别" tabindex="-1">五类地址（必须会判断类别） <a class="header-anchor" href="#五类地址-必须会判断类别" aria-label="Permalink to &quot;五类地址（必须会判断类别）&quot;">​</a></h3><p>按<strong>第一个字节</strong>（前几位）划分：</p><table tabindex="0"><thead><tr><th>类别</th><th>二进制开头</th><th>网络位/主机位</th><th>第一字节范围</th><th>默认掩码</th><th>用途</th></tr></thead><tbody><tr><td><strong>A 类</strong></td><td>0</td><td>8 位 / 24 位</td><td><strong>1 ～ 126</strong></td><td>255.0.0.0</td><td>超大网络（主机数极多）</td></tr><tr><td><strong>B 类</strong></td><td>10</td><td>16 位 / 16 位</td><td><strong>128 ～ 191</strong></td><td>255.255.0.0</td><td>中型网络</td></tr><tr><td><strong>C 类</strong></td><td>110</td><td>24 位 / 8 位</td><td><strong>192 ～ 223</strong></td><td>255.255.255.0</td><td>小型网络</td></tr><tr><td>D 类</td><td>1110</td><td>—</td><td>224 ～ 239</td><td>—</td><td>组播（多播）</td></tr><tr><td>E 类</td><td>1111</td><td>—</td><td>240 ～ 255</td><td>—</td><td>保留（实验）</td></tr></tbody></table><p><strong>判断口诀</strong>：看第一字节——<strong>1～126 是 A，128～191 是 B，192～223 是 C</strong>；中间没写的 127 是特例（见下）。D、E 类不用于给普通主机编址。</p><h3 id="特殊地址-考试直接考结论" tabindex="-1">特殊地址（考试直接考结论） <a class="header-anchor" href="#特殊地址-考试直接考结论" aria-label="Permalink to &quot;特殊地址（考试直接考结论）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址</th><th>含义</th></tr></thead><tbody><tr><td><strong>127.x.x.x</strong></td><td><strong>回环地址</strong>（本机自测，最常见 127.0.0.1），永远不进网络</td></tr><tr><td>主机位<strong>全 0</strong></td><td>代表<strong>网络本身</strong>（网络地址），不能分给主机</td></tr><tr><td>主机位<strong>全 1</strong></td><td>代表<strong>广播地址</strong>（向全网段所有主机广播），不能分给主机</td></tr><tr><td><strong>169.254.x.x</strong></td><td>链路本地地址（DHCP 要不到地址时系统自动配的&quot;临时工&quot;），不是私网地址</td></tr><tr><td>0.0.0.0</td><td>代表所有网络/未指定地址</td></tr><tr><td><strong>255.255.255.255</strong></td><td><strong>受限广播地址</strong>：只在本地网段广播，路由器不转发</td></tr></tbody></table><p><strong>这正是第三节&quot;减 2&quot;的来源</strong>：一个网段里主机位全 0（网络地址）和全 1（广播地址）两个地址被&quot;公家&quot;占用，可用主机数要减 2。</p><h3 id="私网地址-三段-必背" tabindex="-1">私网地址（三段，必背） <a class="header-anchor" href="#私网地址-三段-必背" aria-label="Permalink to &quot;私网地址（三段，必背）&quot;">​</a></h3><p>私网地址是只允许在单位内部使用的地址段，<strong>不会出现在公网路由上</strong>（不同公司的内网可以重用同一批私网地址）：</p><table tabindex="0"><thead><tr><th>段</th><th>范围</th><th>相当于哪类</th></tr></thead><tbody><tr><td><strong>10.0.0.0/8</strong></td><td>10.0.0.0 ～ 10.255.255.255</td><td>A 类</td></tr><tr><td><strong>172.16.0.0/12</strong></td><td><strong>172.16.0.0 ～ 172.31.255.255</strong></td><td>B 类</td></tr><tr><td><strong>192.168.0.0/16</strong></td><td>192.168.0.0 ～ 192.168.255.255</td><td>C 类</td></tr></tbody></table><p><strong>反例演示（三段边界陷阱）</strong>：</p><ol><li><strong>172.32.1.1 不是私网</strong>——私网只到 172.31.255.255，172.32 已越界（是普通 B 类公网地址）。判断只看第二字节是否在 <strong>16～31</strong> 之间。</li><li><strong>192.169.1.1 不是私网</strong>——192.168 段只覆盖第三组为 0～255 的 192.168.x.x；192.169 越界。</li><li><strong>127.0.0.1 不是私网地址</strong>，它是回环地址，和私网是两个概念。</li><li>私网判断题里若出现 169.254.x.x，它是&quot;链路本地&quot;，也不是 RFC 私网三段之一。</li></ol><h3 id="nat-私网主机怎样访问公网-★★" tabindex="-1">NAT：私网主机怎样访问公网 ★★ <a class="header-anchor" href="#nat-私网主机怎样访问公网-★★" aria-label="Permalink to &quot;NAT：私网主机怎样访问公网 ★★&quot;">​</a></h3><p>私网地址不能直接在公网中路由，但家里多台设备仍能共用一个公网地址上网，靠的是路由器上的 <strong>NAT（网络地址转换）</strong>。数据离开内网时，NAT 把报文中的私网源地址改成公网地址；返回报文到达后，再根据转换记录还原并交给原主机。</p><p>家庭路由器常用端口转换（也常称 NAPT/PAT）：不仅转换 IP，还给不同内网连接分配不同的公网端口。例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>192.168.1.10:5000 ── NAT ──→ 203.0.113.8:40001</span></span>
<span class="line"><span>192.168.1.20:5000 ── NAT ──→ 203.0.113.8:40002</span></span></code></pre></div><p>两台主机可以使用相同的内网端口，因为公网侧端口不同，返回数据仍能找到各自的主人。NAT 的主要作用是<strong>节省公网 IPv4 地址、让私网地址访问公网</strong>；它会隐藏内部地址结构，但<strong>不等同于防火墙</strong>，不能因为用了 NAT 就认为系统自动安全。</p><h3 id="默认网关-跨网段通信的第一跳-★★" tabindex="-1">默认网关：跨网段通信的第一跳 ★★ <a class="header-anchor" href="#默认网关-跨网段通信的第一跳-★★" aria-label="Permalink to &quot;默认网关：跨网段通信的第一跳 ★★&quot;">​</a></h3><p><strong>默认网关</strong>通常是“与本机位于同一网段的路由器接口 IP 地址”。主机准备发送数据时，先用自己的子网掩码判断目的 IP 是否同网段：</p><ul><li><strong>同网段</strong>：直接查询目的主机的 MAC 地址并发送，<strong>不经过默认网关</strong>。</li><li><strong>不同网段</strong>：主机不知道完整远程路径，就先把帧交给默认网关，由路由器继续查路由表转发。</li></ul><p>例：主机 A 为 <code>192.168.1.10/24</code>，网关为 <code>192.168.1.1</code>。</p><ul><li>访问 <code>192.168.1.80</code>：前三个字节相同，属于同一 /24 网段，帧直接发给 <code>.80</code> 的 MAC。</li><li>访问 <code>10.0.0.8</code>：不同网段，IP 分组的目的 IP 仍是 <code>10.0.0.8</code>，但第一跳帧的目的 MAC 是网关 <code>192.168.1.1</code> 对应的 MAC。</li></ul><p><strong>常见故障判断</strong>：本机能访问同网段设备，却不能访问任何外网地址，优先检查默认网关或路由；若连同网段设备也不通，则还要检查 IP、掩码、网卡与链路。</p><p><strong>反例演示</strong>：“默认网关可以随便填一个公网 IP”——错。主机必须能在本地链路上把帧交给网关，因此网关接口通常必须和主机在同一子网；否则连第一跳都送不到。</p><p><strong>应试动作</strong>：① 背 A/B/C 三类的第一字节范围与默认掩码；② 私网三段背死（10 / 172.16～172.31 / 192.168），判断时逐字节比边界；③ 记住&quot;主机位全 0 是网络地址、全 1 是广播地址、127 是回环&quot;，这三条既直接出选择题，又是子网计算的理论基础。</p>`,28)])])}const u=d(s,[["render",a]]);export{c as __pageData,u as default};
